      "id": "mahabharata",
      "number": "04",
      "title": "The Mahabharata",
      "author": "Traditionally attributed to Vyasa",
      "year": "Ancient Sanskrit epic tradition",
      "lens": "Ethical",
      "category": "Ethical",
